import os, json
def transform(g):
    from collections import Counter
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    out=[r[:] for r in g]
    pts={}
    for i,r in enumerate(g):
        for j,v in enumerate(r):
            if v!=bg: pts.setdefault(v,set()).add((i,j))
    dirs=[(1,0),(0,1),(1,1),(1,-1)]
    for v,ps in pts.items():
        for dr,dc in dirs:
            # remaining points collinear in this direction
            rem={p for p in ps}
            # decompose into lines along (dr,dc)
            starts=[p for p in rem if (p[0]-dr,p[1]-dc) not in rem]
            for s in starts:
                line=[]; p=s
                while p in rem: line.append(p); rem.discard(p); p=(p[0]+dr,p[1]+dc)
                if len(line)<2: continue
                for q in (line[0],line[-1]):
                    d=-1 if q is line[0] else 1
                    p=(q[0]+d*dr, q[1]+d*dc)
                    while 0<=p[0]<H and 0<=p[1]<W and g[p[0]][p[1]]==bg:
                        out[p[0]][p[1]]=v
                        p=(p[0]+d*dr,p[1]+d*dc)
    return out

