prog='''import json

def transform(grid):
    from collections import Counter
    H, W = len(grid), len(grid[0])
    bg = Counter(c for r in grid for c in r).most_common(1)[0][0]
    cells = [(r, c, v) for r, row in enumerate(grid) for c, v in enumerate(row) if v != bg]
    if not cells:
        return [r[:] for r in grid]
    out = [r[:] for r in grid]
    n = len(cells)
    cr = sum(r for r, _, _ in cells) / n
    cc = sum(c for _, c, _ in cells) / n
    # collect cells per diagonal, split into maximal contiguous same-color runs
    lines = {}
    for r, c, v in cells:
        if v == 0:
            continue  # 0 = marker/hole, never forms rays
        for typ, key in (('d', r - c), ('a', r + c)):
            runs = lines.setdefault((typ, key), [])
            if typ == 'd':
                prev = (r - 1, c - 1)
            else:
                prev = (r - 1, c + 1)
            if runs and runs[-1][-1][2] == v and (runs[-1][-1][0], runs[-1][-1][1]) == prev:
                runs[-1].append((r, c, v))
            else:
                runs.append([(r, c, v)])
    for (typ, _), runlist in lines.items():
        for L in runlist:
            if len(L) < 2:
                continue
            L.sort()
            if typ == 'd':
                fwd, back = (1, 1), (-1, -1)
            else:
                fwd, back = (1, -1), (-1, 1)
            def dist(p):
                return (p[0] - cr) ** 2 + (p[1] - cc) ** 2
            # extend only from the end farther from the sprite centroid, away from it
            start, step = (L[0], back) if dist(L[0]) >= dist(L[-1]) else (L[-1], fwd)
            r, c, v = start
            r += step[0]; c += step[1]
            while 0 <= r < H and 0 <= c < W and grid[r][c] == bg:
                out[r][c] = v
                r += step[0]; c += step[1]
    return out
